/* Fleet code listing — the copy control's behaviour (design.md `code-listing`).
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * nothing here varies between apps.
 *
 * Pairs with code-listing.css. One delegated click listener covers every
 * listing under a root, including ones added later. The text copied is the
 * listing's own `<pre>` text, read with `textContent`, so markup inside it
 * never reaches the clipboard.
 */

'use strict';

const CONFIRM_MS = 1500;

const timers = new WeakMap();
const bound = new WeakSet();

/** Show `text` in the listing's status line and the control's copied state for a moment. */
function say(listing, btn, text, ok) {
  const status = listing.querySelector('.code-listing-status');
  if (status) {
    status.textContent = text;
    if (ok) status.removeAttribute('data-state');
    else status.setAttribute('data-state', 'error');
  }
  if (ok) btn.setAttribute('data-copied', 'true');
  else btn.removeAttribute('data-copied');
  clearTimeout(timers.get(btn));
  timers.set(btn, setTimeout(() => {
    if (status) {
      status.textContent = '';
      status.removeAttribute('data-state');
    }
    btn.removeAttribute('data-copied');
  }, CONFIRM_MS));
}

function onClick(event) {
  const btn = event.target instanceof Element ? event.target.closest('.code-listing-copy') : null;
  if (!btn) return;
  const listing = btn.closest('.code-listing');
  const pre = listing && listing.querySelector('pre');
  if (!pre) return;
  // A missing or refusing clipboard (an insecure page, a denied permission)
  // takes the same path as a rejected write: the header says so.
  Promise.resolve()
    .then(() => navigator.clipboard.writeText(pre.textContent))
    .then(
      () => say(listing, btn, 'Copied', true),
      () => say(listing, btn, 'Copy failed', false),
    );
}

/**
 * Wire every copy control under `root` (default: the document). Safe to call
 * again for the same root.
 *
 * @param {Document|Element} [root]
 */
export function bindCodeListing(root = document) {
  if (bound.has(root)) return;
  bound.add(root);
  root.addEventListener('click', onClick);
}
